{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "Acceptable only if issues 1, 2 and 7–8 are carved out."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Tipping (not deductible) basket; de minimis AUD 10k; thresholds not applicable to Fundamental/Tax/Indemnity claims"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PARTIAL",
      "evidence": "Acceptable for general warranties only if it is a notification period plus a reasonable time to commence proceedings"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Fundamental warranties (title, capacity, authority, share capital) at 100% cap, 6-year period, outside thresholds; independent title verification."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Nothing in cl 12 or 20.5 to limit liability for fraud, wilful concealment or wilful misconduct"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Fair-disclosure standard; data room frozen and escrowed; delete \"publicly searchable records\"; general disclosure not to apply to indemnities or Fundamental Warranties."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete cl 8.3 buyer-knowledge exclusion (or confine to actual knowledge of named individuals, no advisers, no \"discoverable\" standard)."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Bluefen: unconditional consent with cl 11.3 conditions satisfied as a Buyer-only-waivable condition precedent; consider revenue-linked protection."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Riverlark: payout and executed release of security as Completion deliverables; funded from the price at Completion; PPSR discharge."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "DD-005 bonuses plus on-costs deducted from price or paid pre-Completion with evidence; itemised in funds flow."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Ironquay: cleared payment, confirmatory assignment and moral rights consents as Completion deliverables; uncapped specific indemnity for IP title failure."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "DD-006: full incident information pre-signing; assessment completed and any notifications made pre-Completion; uncapped specific indemnity."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Require Seller to either warrant that the renewals are terminable without penalty on ≤90 days' notice or to carve them into the price."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reverse the \"all limitations apply to all Claims\" default; separate regimes for Fundamental, Tax, Specific Indemnities and price adjustments"
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Do not accept DD-012 as the sole evidence."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "The Seller treats tax and IP as \"settled under the general regime\". They are not"
    }
  ],
  "adopts_framing": true,
  "adopts_framing_evidence": "Basket at 1% is broadly market as a \"tipping\" basket",
  "names_manipulation": true
}

